const S=(tid,sid)=>T(tid).study.find(s=>s.id===sid);
const after=(tid,sid,sec)=>{const st=T(tid).study;const i=st.findIndex(s=>s.id===sid);st.splice(i<0?st.length:i+1,0,sec);};
const append=(tid,sid,html)=>{const s=S(tid,sid);if(s)s.html+=html;};
const prepend=(tid,sid,html)=>{const s=S(tid,sid);if(s)s.html=html+s.html;};
const mapRows=(tid,rows)=>{const s=S(tid,tid+'-map');if(!s)return;s.html=s.html.replace('</table></div>',rows+'</table></div>');};
const ph=(slot,title,desc)=>`<figure class="ph" data-slot="${slot}"><div class="phbox"><b>พื้นที่รูป: ${title}</b><br>${desc}</div><figcaption>รอใส่รูป</figcaption></figure>`;
const vocab=(tid,list)=>{const v=T(tid).vocab;list.forEach(w=>{if(!v.some(x=>x.t===w.t||(w.e&&x.e===w.e)))v.push(w);});};
const practice=(tid,list)=>{T(tid).practice.push(...list);};

